@startuml
class User {
  +id : int
  +name : string
  +email : string
  +dateOfBirth : date
}

class Account {
  +accountNumber : int
}

class BusinessAccount extends Account {
  +companyName : string
  +monthlyFee : float
}

class PersonalAccount extends Account {
}

class Page {
  +pageName : string
  +numberOfVisits : int
}

class AdvertisementPage extends Page {
  +bounceRate : float
  +clickThroughRate : float
  +conversionRate : float
}

User "1" -- "0..1" Account : has
Account "1" -- "*" Page : creates
PersonalAccount "0..1" -- "*" Page : granted privileges to
@enduml

